/* রুই মাছ — t8 */
CHAPTER.sections.push({
 "id": "ru-scale",
 "topic": "t8",
 "heading": "পরিচিতি, আঁইশ ও পার্শ্বরেখা",
 "figure": {
  "svg": "<svg viewBox=\"0 0 420 235\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"সাইক্লয়েড আঁইশের গঠন\">\n<style>\n.t{font:13px sans-serif;fill:#222}\n.s{font:12px sans-serif;fill:#333}\n.bg{fill:#fff3e0;stroke:#a1887f;stroke-width:1.5}\n.c{fill:none;stroke:#a1887f;stroke-width:1.2;transform-origin:110px 115px;animation:ruiScalegrow 6s ease-out infinite}\n.a{fill:none;stroke:#5d4037;stroke-width:3;transform-origin:110px 115px;animation:ruiScalegrow 6s ease-out infinite}\n.r{stroke:#bcaaa4;stroke-width:1}\n.ld{stroke:#555;stroke-width:1;stroke-dasharray:3 2}\n@keyframes ruiScalegrow{0%{transform:scale(.15);opacity:0}25%{opacity:1}55%,100%{transform:scale(1);opacity:1}}\n</style>\n<circle class=\"bg\" data-p=\"disc\" cx=\"110\" cy=\"115\" r=\"90\"/>\n<line class=\"r\" x1=\"110\" y1=\"115\" x2=\"110\" y2=\"30\"/><line class=\"r\" x1=\"110\" y1=\"115\" x2=\"52\" y2=\"52\"/><line class=\"r\" x1=\"110\" y1=\"115\" x2=\"168\" y2=\"52\"/><line class=\"r\" x1=\"110\" y1=\"115\" x2=\"175\" y2=\"152\"/><line class=\"r\" x1=\"110\" y1=\"115\" x2=\"45\" y2=\"152\"/><line class=\"r\" x1=\"110\" y1=\"115\" x2=\"110\" y2=\"200\"/>\n<circle class=\"c\" data-p=\"focus\" cx=\"110\" cy=\"115\" r=\"22\" style=\"animation-delay:0s\"/>\n<circle class=\"c\" cx=\"110\" cy=\"115\" r=\"35\" style=\"animation-delay:.4s\"/>\n<circle class=\"a\" cx=\"110\" cy=\"115\" r=\"50\" style=\"animation-delay:.8s\"/>\n<circle class=\"c\" cx=\"110\" cy=\"115\" r=\"64\" style=\"animation-delay:1.2s\"/>\n<circle class=\"c\" cx=\"110\" cy=\"115\" r=\"78\" style=\"animation-delay:1.6s\"/>\n<circle data-p=\"focus\" cx=\"110\" cy=\"115\" r=\"5\" fill=\"#d84315\"/>\n<line class=\"ld\" data-p=\"focus\" x1=\"236\" y1=\"112\" x2=\"116\" y2=\"115\"/><text class=\"t\" x=\"240\" y=\"116\">ফোকাস (কেন্দ্র)</text>\n<line class=\"ld\" x1=\"236\" y1=\"76\" x2=\"138\" y2=\"95\"/><text class=\"t\" x=\"240\" y=\"80\">সারকুলী (ঘনবৃত্ত)</text>\n<line class=\"ld\" x1=\"236\" y1=\"42\" x2=\"145\" y2=\"73\"/><text class=\"t\" x=\"240\" y=\"46\">অ্যানুলী (বৃদ্ধি-দাগ)</text>\n<line class=\"ld\" x1=\"236\" y1=\"158\" x2=\"165\" y2=\"147\"/><text class=\"t\" x=\"240\" y=\"162\">রেডিই (কেন্দ্র থেকে রেখা)</text>\n<text class=\"s\" x=\"210\" y=\"196\">সাইক্লয়েড = গোল, কাঁটা নেই</text>\n<text class=\"s\" x=\"210\" y=\"214\">পার্শ্বরেখায় আঁইশ ৪১-৪২টি</text>\n</svg>",
  "caption": "সাইক্লয়েড আঁইশ: মাঝখানে ফোকাস, তার বাইরে একের পর এক ঘনবৃত্ত যোগ হয়ে আঁইশ বাড়ে।"
 },
 "note": "রুই মাছের বৈজ্ঞানিক নাম <span class=\"k\">Labeo rohita</span>। এটি <span class=\"k\">Cyprinidae</span> গোত্রের মাছ (প্রশ্নে \"বর্গ\" লেখা থাকলেও Cyprinidae আসলে গোত্র বা family; Anguillidae, Cynoglossidae, Bagridae অন্য গোত্র)। শ্রেণি <span class=\"k\">Actinopterygii</span> (রশ্মি-পাখনাওয়ালা মাছ); এই শ্রেণির বৈশিষ্ট্য <span class=\"k\">সাইক্লয়েড আঁইশ</span>। গ্যানয়েড, প্ল্যাকয়েড আঁইশ আর হেটোরোসার্কাল লেজ অন্য দলের (হাঙর, স্টার্জন) বৈশিষ্ট্য।<br><b>আঁইশ:</b> রুইয়ের আঁইশ <span class=\"k\">সাইক্লয়েড</span> বা সার্কুলার (গোলাকার, কাঁটাহীন); কাঁটাযুক্ত হলে টিনয়েড হতো, রুইয়ের তা নয়। আঁইশে <span class=\"k\">চুন ও কোলাজেন তন্তু</span> থাকে। আঁইশের মাঝখানের কেন্দ্রীয় অংশের নাম <span class=\"k\">ফোকাস</span>। ফোকাসের চারপাশে ঘনবৃত্ত <span class=\"k\">সারকুলী</span>, বৃদ্ধির দাগ <span class=\"k\">অ্যানুলী</span>, আর ফোকাস থেকে বাইরে ছড়ানো রেখা <span class=\"k\">রেডিই</span>। আঁইশের বৃদ্ধি হয় <span class=\"k\">বসন্তকালে</span> (শীত, শরৎ, বর্ষা নয়)।<br><b>পার্শ্বরেখা:</b> দেহের দুই পাশে লম্বা রেখা; এতে <span class=\"k\">৪১-৪২টি</span> আঁইশ থাকে। পার্শ্বরেখা রুইয়ের <span class=\"k\">সংবেদী অঙ্গ</span> (পানির কম্পন ও স্রোত টের পায়); কানকুয়া, পটকা বা ব্রাঙ্কিওস্টেগাল পর্দা সংবেদী অঙ্গ নয়।<br><b>অন্যান্য:</b> দেহের অক্ষীয়তলে <span class=\"k\">৩টি</span> ছিদ্র থাকে। রুই মাছ <span class=\"k\">১৪°C</span>-এর নিচের তাপমাত্রায় বাঁচতে পারে না (বইয়ে ছাপা ছিল ২৪°C, কিন্তু বইয়ের নিজের Note বলছে সঠিক উত্তর ১৪°C)।",
 "why": "রুই মিঠাপানির মাছ, ঠান্ডায় বিপাক ধীর হয়ে যায়, তাই খুব শীতে (১৪°C-এর নিচে) টিকতে পারে না। বসন্তে তাপমাত্রা ও খাবার বাড়ে, তাই আঁইশে নতুন বৃত্ত যোগ হয়। আঁইশ সাইক্লয়েড (কাঁটাহীন) বলেই মসৃণ, তাই সাঁতারে পানির বাধা কম। পার্শ্বরেখায় পানির কম্পন ধরা পড়ে, তাই সেটাই সংবেদী অঙ্গ।",
 "mnemonic": "সাইক্লয়েড = সাইকেলের চাকা (kyklos = বৃত্ত)। হাব = ফোকাস (মাঝখান), টায়ারের গোল দাগ = সারকুলী, চাকার স্পোক = রেডিই (radius-এর বহুবচন)। চাকায় কাঁটা নেই, তাই কাঁটাযুক্ত নয়।",
 "story": "বসন্তের এক সকালে রুই মাছটা পুকুরে আরাম করে ভাসছে; পানি গরম হচ্ছে বলে ওর আঁইশে নতুন বৃত্ত যোগ হচ্ছে। প্রতিটা আঁইশ সাইকেলের চাকার মতো গোল: মাঝখানে ফোকাস, তার চারপাশে ঘনবৃত্ত সারকুলী, মোটা বৃদ্ধির দাগ অ্যানুলী, আর হাবের থেকে বেরোনো স্পোক রেডিই। দেহের দুই পাশে পার্শ্বরেখা বরাবর ৪১-৪২টা আঁইশ সারি বেঁধে আছে, ওখান দিয়েই সে পানির কম্পন টের পায়। পেটের নিচে তিনটা ছিদ্র। হঠাৎ ঠান্ডা স্রোত এল, তাপমাত্রা ১৪°C-এর নিচে নামলে সে আর বাঁচবে না। ও Cyprinidae গোত্রের কার্প, Actinopterygii শ্রেণির রশ্মি-পাখনার মাছ।",
 "traps": [
  "গ্যানয়েড বা প্ল্যাকয়েড দেখলে বাদ: ওগুলো অন্য মাছের (হাঙর, স্টার্জন) আঁইশ, রুইয়ের সাইক্লয়েড।",
  "টিনয়েড বা কন্টকযুক্ত দেখলে বাদ: রুইয়ের আঁইশ কাঁটাহীন গোলাকার।",
  "আঁইশের কেন্দ্র প্রশ্নে অ্যানুলী, সারকুলী বা রেডিই দেখলে বাদ: কেন্দ্র মানে ফোকাস।",
  "পার্শ্বরেখার আঁইশে ৩১, ৫১ বা ৬১ দেখলে বাদ: ঠিক সংখ্যা ৪১-৪২।",
  "সংবেদী অঙ্গ প্রশ্নে কানকুয়া, পটকা বা ব্রাঙ্কিওস্টেগাল পর্দা দেখলে বাদ: উত্তর পার্শ্বরেখা।",
  "২৪°C, ১৬°C বা ২০°C দেখলে বাদ: বইয়ের Note অনুযায়ী ১৪°C।"
 ]
});
CHAPTER.sections.push({
 "id": "ru-fin",
 "topic": "t8",
 "heading": "পাখনা: জোড়া, অযুগ্ম ও রশ্মির সংখ্যা",
 "figure": {
  "svg": "<svg viewBox=\"0 0 420 240\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"রুই মাছের পাখনা\">\n<style>\n.t{font:12px sans-serif;fill:#222}\n.body{fill:#e3f2fd;stroke:#1565c0;stroke-width:1.5}\n.pair{fill:#64b5f6;stroke:#0d47a1;stroke-width:1.2}\n.unp{fill:#ffb74d;stroke:#e65100;stroke-width:1.2}\n.ld{stroke:#555;stroke-width:1;stroke-dasharray:3 2}\n.tail{transform-origin:290px 115px;animation:ruiFinsw 1.6s ease-in-out infinite}\n.pec{transform-origin:100px 130px;animation:ruiFinfl 1.2s ease-in-out infinite}\n.pel{transform-origin:185px 152px;animation:ruiFinfl 1.2s ease-in-out infinite .3s}\n@keyframes ruiFinsw{0%,100%{transform:rotate(-12deg)}50%{transform:rotate(12deg)}}\n@keyframes ruiFinfl{0%,100%{transform:rotate(-8deg)}50%{transform:rotate(8deg)}}\n</style>\n<polygon class=\"unp\" data-p=\"unp dorsal\" points=\"120,82 160,52 210,60 216,90\"/>\n<polygon class=\"unp\" data-p=\"unp anal\" points=\"225,147 240,176 270,166 265,132\"/>\n<g class=\"tail\"><polygon class=\"unp\" data-p=\"unp tail\" points=\"288,115 348,78 332,115 348,152\"/></g>\n<path class=\"body\" d=\"M45,115 C70,70 200,65 290,105 L290,125 C200,165 70,160 45,115 Z\"/>\n<path d=\"M84,88 C98,105 98,125 84,142\" fill=\"none\" stroke=\"#1565c0\" stroke-width=\"1.5\"/>\n<circle cx=\"64\" cy=\"108\" r=\"4\" fill=\"#0d47a1\"/>\n<g class=\"pec\"><polygon class=\"pair\" data-p=\"pair pec\" points=\"92,128 122,172 130,135\"/></g>\n<g class=\"pel\"><polygon class=\"pair\" data-p=\"pair pel\" points=\"165,150 182,186 206,152\"/></g>\n<line class=\"ld\" x1=\"60\" y1=\"53\" x2=\"84\" y2=\"92\"/><text class=\"t\" x=\"8\" y=\"48\">কানকো</text>\n<line class=\"ld\" x1=\"185\" y1=\"34\" x2=\"185\" y2=\"58\"/><text class=\"t\" x=\"125\" y=\"30\">পৃষ্ঠ (অযুগ্ম)</text>\n<line class=\"ld\" x1=\"385\" y1=\"48\" x2=\"345\" y2=\"90\"/><text class=\"t\" x=\"262\" y=\"24\">পুচ্ছ (অযুগ্ম): ১৯ রশ্মি</text><text class=\"t\" x=\"290\" y=\"40\">প্রধান চলন-পাখনা</text>\n<line class=\"ld\" x1=\"62\" y1=\"196\" x2=\"108\" y2=\"156\"/><text class=\"t\" x=\"8\" y=\"210\">বক্ষ (জোড়া)</text><text class=\"t\" x=\"8\" y=\"226\">রশ্মি ১৭-১৮</text>\n<line class=\"ld\" x1=\"188\" y1=\"204\" x2=\"190\" y2=\"186\"/><text class=\"t\" x=\"140\" y=\"220\">শ্রোণি (জোড়া)</text>\n<line class=\"ld\" x1=\"262\" y1=\"198\" x2=\"254\" y2=\"170\"/><text class=\"t\" x=\"228\" y=\"214\">পায়ু (অযুগ্ম)</text>\n<rect x=\"340\" y=\"196\" width=\"12\" height=\"12\" class=\"pair\"/><text class=\"t\" x=\"358\" y=\"207\">জোড়া</text>\n<rect x=\"340\" y=\"216\" width=\"12\" height=\"12\" class=\"unp\"/><text class=\"t\" x=\"358\" y=\"227\">অযুগ্ম</text>\n</svg>",
  "caption": "নীল পাখনা জোড়া (বক্ষ ও শ্রোণি), কমলা পাখনা অযুগ্ম (পৃষ্ঠ, পায়ু, পুচ্ছ); লেজ নেড়েই মাছ সামনে যায়।"
 },
 "note": "রুই মাছের পাখনা দুই রকম। <span class=\"k\">জোড়া (যুগ্ম) পাখনা</span> <span class=\"k\">২ ধরনের</span>: <span class=\"k\">বক্ষ পাখনা</span> ও <span class=\"k\">শ্রোণি পাখনা</span>; মোট জোড় পাখনা <span class=\"k\">৪টি</span> (দুই জোড়া)। <span class=\"k\">অযুগ্ম পাখনা</span> <span class=\"k\">৩ ধরনের</span>: <span class=\"k\">পৃষ্ঠ</span>, <span class=\"k\">পায়ু</span> ও <span class=\"k\">পুচ্ছ</span>।<br>কানকোর পেছনে যে পাখনা, সেটা <span class=\"k\">বক্ষ পাখনা</span> (শ্রেণি পাখনা বলে কিছু নেই, ওটা অপশনের ফাঁদ); এতে রশ্মি <span class=\"k\">১৭-১৮টি</span>। <span class=\"k\">পুচ্ছ পাখনা</span> লেজে থাকে: রশ্মি <span class=\"k\">১৯টি</span>, আকৃতি <span class=\"k\">হোমোসার্কাল</span> (দুই ভাগ সমান; হেটোরোসার্কাল, ডাইফিসার্কাল, প্রোটোসার্কাল নয়), আর এটাই রুইয়ের <span class=\"k\">প্রধান চলন-পাখনা</span>।<br>দ্রুত মনে রাখার ছক: জোড়া = বক্ষ + শ্রোণি (২ ধরন, ৪টি); অযুগ্ম = পৃষ্ঠ + পায়ু + পুচ্ছ (৩ ধরন)।",
 "why": "জোড়া পাখনা (বক্ষ, শ্রোণি) দেহের ভারসাম্য রাখে ও দিক বদলাতে সাহায্য করে। পুচ্ছ পাখনা সবচেয়ে বড় ও শক্তিশালী পেশির সাথে যুক্ত, তাই লেজ নেড়ে ধাক্কা দিয়েই মাছ সামনে এগোয়, এটাই প্রধান চলন-পাখনা। হোমোসার্কাল লেজের দুই ভাগ সমান, তাই ধাক্কা সোজা সামনের দিকে যায়।",
 "mnemonic": "ক্রিকেটের স্কোর: ১৭-১৮ রানে বক্ষ আউট, আর ১৯ রানে পুচ্ছ। আরেকটা সুর: অযুগ্ম তিনটাই 'প' দিয়ে শুরু: পৃষ্ঠ, পায়ু, পুচ্ছ (প-প-প)। জোড়া দুটো: বক্ষ আর শ্রোণি, মানে বুক আর কোমর (হাত আর পা)।",
 "story": "ক্রিকেট ম্যাচে মাঠের নদীর পাড়ে বসে এক ছেলে রুই মাছ ধরেছে। কানকোর ঠিক পেছনে দেখো, বক্ষ পাখনা, ওতে ১৭-১৮টা রশ্মি; তার একটু নিচে কোমরের শ্রোণি পাখনা। এই দুটোই জোড়া, দুই ধরন, মোট চারটা। পিঠে পৃষ্ঠ, পেটের পেছনে পায়ু, আর লেজে পুচ্ছ, এই তিনটা অযুগ্ম, একা একা। পুচ্ছের রশ্মি ঠিক ১৯টা, দুই ভাগ সমান, তাই হোমোসার্কাল। ছেলেটা দেখল মাছটা লেজ নেড়ে সামনে ধাক্কা দিচ্ছে, কারণ পুচ্ছই প্রধান চলন-পাখনা।",
 "traps": [
  "\"শ্রেণি পাখনা\" দেখলে বাদ: এমন কোনো পাখনা নেই, বক্ষ লিখতে গিয়ে ফাঁদ।",
  "পৃষ্ঠ, পায়ু বা পুচ্ছ দেখলে \"জোড়া/যুগ্ম\" প্রশ্নে বাদ: ওরা অযুগ্ম।",
  "হেটোরোসার্কাল, ডাইফিসার্কাল বা প্রোটোসার্কাল দেখলে বাদ: রুইয়ের লেজ হোমোসার্কাল।",
  "পুচ্ছের রশ্মি ১৩, ১৫ বা ২৬ দেখলে বাদ: সঠিক সংখ্যা ১৯।",
  "বক্ষ পাখনার রশ্মি ১১-১২, ১৩-১৪ বা ১৫-১৬ দেখলে বাদ: সঠিক ১৭-১৮।",
  "\"কত ধরনের\" আর \"কতটি\" আলাদা করো: যুগ্ম পাখনা ২ ধরন, জোড় পাখনা ৪টি; অযুগ্ম ৩ ধরন।"
 ]
});
